"use client";
import LegacyPage from "../components/LegacyPage";

const TITLE = "Averages — Assignments";
const STYLE_CSS = "\n  /* ---------- Shared design system — copied verbatim from the other\n     top-level pages (/home//courses) so this reads as the same\n     app. See architecture-decisions.md re: promoting this to an actual\n     shared stylesheet once there's a build step. ---------- */\n  :root {\n    --accent: #d94a2b;\n    --accent-dark: #a8331a;\n    --accent-ring: rgb(from var(--accent) r g b / 0.35);\n    --page-bg-start: #f17b53;\n    --page-bg-end: #930500;\n    --panel-bg: #eaeaec;\n    --panel-inner: #dcdce0;\n    --text-dark: #14151f;\n    --text-muted: #4b4d63;\n    --text-faint: #83849a;\n    --border: #cfcfd6;\n    --window-radius-lg: 22px;\n    --window-radius-md: 14px;\n    --window-radius-sm: 10px;\n    --grade-good: #2f7d54;\n    --grade-mid: #a67a22;\n    --grade-bad: #b6432f;\n  }\n\n  * { box-sizing: border-box; }\n\n  /* Scrollbars app-wide: a slim, permanently-visible, rounded gray bar\n     sitting slightly inset from the true edge of its scrollable area --\n     like a normal OS/Gmail-style scrollbar, not hidden and not\n     hover-gated. (An earlier hover-only version turned out unreliable:\n     the outer page counts as \"hovered\" almost the entire time you're\n     using it, so it either showed constantly or never, depending on the\n     browser -- not the meaningful hover signal it needed to be.)\n     Scrolling itself always works via wheel/trackpad/touch/keys either\n     way. One universal rule (the `*` selector) so it covers every\n     scrollable element automatically — the outer page scroll, every\n     popup/modal, every internal list — without repeating it per\n     element. (The bottom nav's own horizontal scroll strip is a\n     deliberate exception — see .app-nav-inner further down — that one\n     stays permanently hidden as a mobile overflow safety net.) */\n  * {\n    scrollbar-width: thin;\n    scrollbar-color: rgba(20, 21, 31, 0.28) transparent;\n  }\n  *::-webkit-scrollbar { width: 10px; height: 10px; }\n  *::-webkit-scrollbar-track { background: transparent; }\n  *::-webkit-scrollbar-thumb {\n    background-color: rgba(20, 21, 31, 0.28);\n    border-radius: 999px;\n    border: 2px solid transparent;\n    background-clip: padding-box; /* the transparent border creates the\n      inset gap around the thumb, so it reads as sitting inside the\n      window rather than flush against the very edge */\n  }\n  *::-webkit-scrollbar-thumb:hover { background-color: rgba(20, 21, 31, 0.45); }\n  *::-webkit-scrollbar-corner { background: transparent; }\n\n  /* Declared so the browser themes ITS OWN chrome — scrollbars, the\n\n     overscroll gutter, form controls — against this page rather than\n\n     guessing. Without it Firefox drew a light-theme scrollbar over the\n\n     dark canvas and tinted it (Martin saw it as pink on a blue\n\n     background). LegacyPage's applyStoredTheme() updates both of these\n\n     to match whatever background the user actually saved. */\n\n  html {\n\n    color-scheme: dark;\n\n    background-color: #0c0c0e;\n\n  }\n\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    min-height: 100%;\n    font-family: \"puffin\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  }\n\n  body {\n    height: 100vh; /* fixed, not min -- body itself no longer scrolls */\n    overflow: hidden; /* scrolling now happens inside .page (see below), so\n      the scrollbar sits at the edge of the app's own window/card instead of\n      out at the browser's outer edge, over the wallpaper margin */\n    /* Neutral black instead of a baked-in accent gradient here —\n       2026-09-11, per Martin. This is only ever visible for a split\n       second on reload/navigation, before applyStoredTheme() (or this\n       page's own appearance-reading script) sets the user's actual\n       saved background over it. The old default was the sample\n       red-orange gradient baked into this file, which read as a real\n       glitch flashing in between pages; a neutral black reads as\n       \"still loading\" instead, and matches the app's own Black\n       preset (#0c0c0e) so it's not a color that appears nowhere else\n       in the app. */\n    background-color: #0c0c0e;\n    background-image: none;\n    background-size: cover;\n    background-position: center;\n    background-repeat: no-repeat;\n    padding: 40px 24px 100px;\n    display: flex;\n    justify-content: center;\n  }\n\n  .page {\n    width: 100%;\n    max-width: 980px;\n    align-self: stretch; /* fill body's available height regardless of\n      whatever align-items body declares, so there's a bounded box to\n      scroll within */\n    min-height: 0; /* flexbox gotcha: without this, a flex item won't\n      shrink below its content size, which breaks overflow scrolling */\n    overflow-y: auto; /* the actual scroll happens here -- .card grows to\n      its natural content height and .page scrolls as a whole */\n    overflow-x: hidden;\n  }\n\n  /* ---------- Top bar ---------- */\n  .topbar {\n    display: flex;\n    align-items: flex-end;\n    justify-content: space-between;\n    margin: 0 4px 18px;\n  }\n\n  h1.title {\n    color: #ffffff;\n    font-size: clamp(1.6rem, 3.4vw, 2.1rem);\n    font-weight: 900;\n    font-style: italic;\n    letter-spacing: -0.01em;\n    margin: 0;\n    transform: skewX(-2deg);\n    display: inline-block;\n  }\n  .subtitle {\n    color: rgba(255,255,255,0.85);\n    font-weight: 700;\n    font-style: italic;\n    font-size: 0.9rem;\n    margin: 2px 0 0 2px;\n  }\n\n  .profile-menu-wrap { position: relative; flex-shrink: 0; }\n  .profile-btn {\n    width: 42px;\n    height: 42px;\n    border-radius: 50%;\n    background: rgba(255,255,255,0.2);\n    border: 2px solid rgba(255,255,255,0.5);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-weight: 800;\n    font-size: 0.95rem;\n    cursor: pointer;\n    flex-shrink: 0;\n  }\n  .profile-menu {\n    position: absolute;\n    top: calc(100% + 10px);\n    right: 0;\n    min-width: 160px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 25;\n  }\n  .profile-menu-item {\n    display: block;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.86rem;\n    color: var(--text-dark);\n    padding: 9px 12px;\n    cursor: pointer;\n  }\n  .profile-menu-item:hover { background: var(--panel-inner); }\n  .profile-menu-item.signout { color: var(--grade-bad); }\n\n  /* ---------- One card, same as every other page ---------- */\n  .card {\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    padding: 6px;\n  }\n  .card-inner {\n    padding: 22px 24px 20px;\n  }\n\n  .section-head {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    margin-bottom: 4px;\n  }\n  .section-head h2 {\n    font-size: 1rem;\n    font-weight: 800;\n    font-style: italic;\n    color: var(--text-dark);\n    margin: 0;\n  }\n  .assign-total {\n    font-size: 0.76rem;\n    font-weight: 700;\n    color: var(--text-faint);\n  }\n\n  /* ---------- Filter pills — same component as /course-home's\n     Assignment List widget, except the active state uses --accent\n     rather than --course-color: this page spans all six courses, so\n     there's no single course color to key off of. ---------- */\n  .assign-filters { display: flex; gap: 6px; flex-wrap: wrap; margin: 14px 0 6px; }\n  .assign-filter {\n    background: var(--panel-inner);\n    border: none;\n    border-radius: 999px;\n    padding: 5px 11px;\n    font-family: inherit;\n    font-weight: 800;\n    font-size: 0.68rem;\n    color: var(--text-muted);\n    cursor: pointer;\n  }\n  .assign-filter:hover { color: var(--text-dark); }\n  .assign-filter.active { background: var(--accent); color: #fff; }\n  .assign-filter:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n\n  /* Class filter — a dropdown among the status pills above, added\n     2026-09-03 (per Martin: \"on the all assignments we should just add a\n     class filter dropdown ... same shape and color as the other filters\n     but will have a down arrow, which when selected will be the accent\n     color until they reset it\"). Same pill shape/background/type scale\n     as .assign-filter, plus a chevron to read as a dropdown rather than\n     a toggle, and the same active-state accent fill the status pills\n     use, applied for as long as a specific class (not \"All Classes\")\n     stays selected. **Position (2026-09-03 follow-up, per Martin)**: sits\n     right after \"All\" by default — a real DOM position (not just visual,\n     so tab order matches what's on screen — see the JS's\n     `moveClassFilterWrap()`), moving to the end of the row (after Graded)\n     with a FLIP-animated slide while a class stays selected, and back\n     next to \"All\" the moment it's reset. **Rebuilt as a custom dropdown\n     (2026-09-03, second follow-up, per Martin: \"can you make a custom\n     dropdown for selecting a class to filter by\")**: was a native\n     `<select>` at first — swapped for a real button + floating listbox\n     panel (the same open/close/outside-click/Escape convention this\n     page's own profile menu already uses, just role=\"listbox\" instead of\n     role=\"menu\"), so the option list can carry each course's own color\n     dot and match the app's own visual language instead of the browser's\n     native dropdown chrome. Still fully keyboard-operable (a real\n     `<button>` plus real `<button role=\"option\">` rows, not a `<div>`\n     stack), just no longer a native form control. */\n  .assign-filter-select-wrap { position: relative; display: inline-flex; }\n  .assign-filter-select-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 5px;\n    background: var(--panel-inner);\n    border: none;\n    border-radius: 999px;\n    padding: 5px 10px;\n    font-family: inherit;\n    font-weight: 800;\n    font-size: 0.68rem;\n    color: var(--text-muted);\n    cursor: pointer;\n  }\n  .assign-filter-select-wrap:not(.active) .assign-filter-select-btn:hover { color: var(--text-dark); }\n  .assign-filter-select-wrap.active .assign-filter-select-btn { background: var(--accent); color: #fff; }\n  .assign-filter-select-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .assign-filter-arrow { width: 8px; height: 8px; flex-shrink: 0; color: inherit; }\n\n  .assign-class-menu {\n    position: absolute;\n    top: calc(100% + 8px);\n    left: 0;\n    min-width: 170px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0, 0, 0, 0.5);\n    padding: 6px;\n    z-index: 25;\n  }\n  .assign-class-option {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.8rem;\n    color: var(--text-dark);\n    padding: 8px 10px;\n    cursor: pointer;\n  }\n  .assign-class-option:hover, .assign-class-option.selected { background: var(--panel-inner); }\n  .assign-class-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }\n\n  .assign-group-label { font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-faint); margin: 16px 0 2px; }\n  .assign-group-label:first-child { margin-top: 0; }\n\n  /* ---------- Assignment row — the draft PDF's row shape (bold-italic\n     class name on top, a lighter assignment-title line beneath) laid\n     over the status-tick/due-date component every other Assignment\n     List already uses, so this page matches both the draft and the\n     rest of the app. Course color comes in per-row via a custom\n     property, since (unlike /course-home) this page isn't scoped\n     to one course's --course-color. **Divider removed, padding grows\n     when unfiltered (2026-09-03, per Martin)**: the `border-bottom`\n     divider between rows is gone — rows are separated by spacing alone\n     now, not a rule line. That freed-up padding grew to compensate\n     (10px → 16px) for the default \"All Classes\" view; the class-filtered\n     state below dials it back down, since that view's rows carry less\n     visual weight (course name shrinks to a small caption) and don't\n     need as much breathing room. ---------- */\n  .assign-row { display: flex; align-items: flex-start; gap: 10px; padding: 16px 0; }\n  #assignListBody.class-filtered .assign-row { padding: 10px 0; }\n  .assign-tick { width: 4px; align-self: stretch; min-height: 40px; border-radius: 999px; flex-shrink: 0; background: var(--text-faint); }\n  .assign-row.overdue .assign-tick { background: var(--grade-bad); }\n  .assign-row.graded .assign-tick { background: var(--grade-good); }\n  .assign-row.upcoming .assign-tick { background: var(--row-course-color, var(--accent)); }\n  .assign-row.submitted .assign-tick { background: var(--grade-mid); }\n  .assign-text { flex: 1; min-width: 0; display: flex; flex-direction: column; }\n  .assign-course { order: 0; font-weight: 800; font-style: italic; font-size: 0.86rem; margin: 0; letter-spacing: -0.005em; }\n  .assign-title { order: 1; font-weight: 500; font-size: 0.82rem; color: var(--text-muted); margin: 2px 0 0; }\n  .assign-meta { order: 2; font-size: 0.68rem; color: var(--text-faint); margin: 3px 0 0; text-transform: uppercase; letter-spacing: 0.03em; font-weight: 800; }\n\n  /* Class-filtered typography swap (2026-09-03, per Martin: \"the name of\n     the assignment should get bigger and the course name get smaller and\n     move to the bottom\") — every row already shows the same one class\n     once a class filter is active, so the course name stops earning top\n     billing: the assignment title takes over as the bold headline, and\n     the course name demotes to a small caption below the type label.\n     `.assign-text` is a column flexbox specifically so this can reorder\n     via `order` alone — no DOM changes needed between the two states. */\n  #assignListBody.class-filtered .assign-title { order: 0; font-size: 0.98rem; font-weight: 800; color: var(--text-dark); margin: 0; }\n  #assignListBody.class-filtered .assign-meta { order: 1; margin: 3px 0 0; }\n  #assignListBody.class-filtered .assign-course { order: 2; font-size: 0.66rem; font-weight: 700; margin: 4px 0 0; }\n  .assign-due { font-size: 0.72rem; font-weight: 700; color: var(--text-faint); white-space: nowrap; text-align: right; flex-shrink: 0; padding-top: 1px; }\n  .assign-row.overdue .assign-due { color: var(--grade-bad); }\n  .assign-row.graded .assign-due { color: var(--grade-good); }\n  .assign-row.submitted .assign-due { color: var(--grade-mid); }\n  .assign-empty { font-size: 0.8rem; color: var(--text-faint); font-style: italic; padding: 10px 0; }\n\n  /* Rows are clickable — each opens its own /assignment detail\n     page (2026-08-29, per Martin's singular-assignment draft). */\n  .assign-row { cursor: pointer; border-radius: var(--window-radius-sm); }\n  .assign-row:hover { background: var(--panel-inner); }\n  .assign-row:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring) inset; }\n\n  /* ---------- Bottom nav — verbatim from every other page ---------- */\n  .app-nav {\n    position: fixed;\n    left: 0;\n    right: 0;\n    bottom: 20px;\n    display: flex;\n    justify-content: center;\n    padding: 0 20px;\n    z-index: 10;\n    pointer-events: none;\n  }\n  .app-nav-inner {\n    display: flex;\n    gap: 4px;\n    width: 100%;\n    max-width: 940px;\n    overflow-x: auto;\n    scrollbar-width: none;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    padding: 0 8px;\n    pointer-events: auto;\n  }\n  .app-nav-inner::-webkit-scrollbar { display: none; }\n  .nav-link {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 1;\n    min-width: 0;\n    padding: 12px 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-link .label { display: block; max-width: 100%; font-size: 0.72rem; font-weight: 800; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; }\n  .nav-link:hover .label { color: var(--text-muted); }\n  .nav-link .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-link.active .label { color: var(--text-dark); }\n  .nav-link.active .dot { background: var(--accent); }\n  /* ---------- \"More\" overflow (2026-10-01, per Martin: \"if the text has\n     to get ... we should add a more button on the far right side with a\n     list of the other options\"). Labels never truncate: when they would,\n     the rightmost pages move into the More menu instead. ---------- */\n  .nav-link[hidden], .nav-more[hidden], .nav-more-menu[hidden] { display: none; }\n  /* While the More menu is open the whole bar sits above everything else on\n     the page (sticky headers, pop-ups, the edit button go up to z-index 90),\n     so the menu is never drawn underneath them. */\n  .app-nav.more-open { z-index: 1000; }\n  .nav-more {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 0 0 auto;\n    position: relative;\n    margin-left: 4px;\n    padding: 12px 16px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-more .label { display: flex; align-items: center; height: 1.2em; font-size: 0.72rem; color: var(--text-faint); }\n  .nav-more .label svg { display: block; fill: currentColor; }\n  /* thin divider between the pages and the dots */\n  .nav-more::before { content: \"\"; position: absolute; left: 0; top: 12px; bottom: 12px; width: 1px; background: var(--border, #cfcfd6); }\n  .nav-more:hover .label, .nav-more[aria-expanded=\"true\"] .label { color: var(--text-dark); }\n  .nav-more .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-more.has-active .label { color: var(--text-dark); }\n  .nav-more.has-active .dot { background: var(--accent); }\n  .nav-more:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-menu {\n    position: absolute;\n    bottom: calc(100% + 8px);\n    right: 20px;\n    min-width: 168px;\n    padding: 8px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);\n    pointer-events: auto;\n  }\n  .nav-more-item {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    font-size: 0.8rem;\n    font-weight: 800;\n    color: var(--text-faint);\n    text-align: left;\n    padding: 12px 12px;\n    border-radius: 8px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n  }\n  .nav-more-item:hover, .nav-more-item:focus-visible { outline: none; color: var(--text-dark); box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-item.active { color: var(--text-dark); }\n  .nav-more-item.active span { position: relative; display: inline-block; padding-bottom: 6px; margin-bottom: -6px; }\n  .nav-more-item.active span::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  /* Labels sit centered in the bar; the active page is underlined in the\n     accent color instead of marked with a dot (2026-10-01, per Martin). */\n  .app-nav-inner .nav-link, .app-nav-inner .nav-more { justify-content: center; gap: 0; padding-top: 10px; padding-bottom: 10px; }\n  .app-nav-inner .nav-link .dot, .app-nav-inner .nav-more .dot { display: none; }\n  .app-nav-inner .nav-link .label, .app-nav-inner .nav-more .label { position: relative; padding: 6px 0; }\n  .app-nav-inner .nav-link.active .label::after, .app-nav-inner .nav-more.has-active .label::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  @media (max-width: 520px) {\n    .nav-more { padding: 10px 12px 8px; }\n    .nav-more::before { top: 10px; bottom: 10px; }\n    .app-nav-inner .nav-link, .app-nav-inner .nav-more { padding-top: 8px; padding-bottom: 8px; }\n    .nav-more .label { font-size: 0.58rem; }\n  }\n  .nav-link:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  @media (max-width: 520px) {\n    .nav-link { min-width: 0; padding: 10px 3px 8px; }\n    .nav-link .label { font-size: 0.58rem; }\n  }\n";
const BODY_HTML = "\n  <div class=\"page\">\n    <div class=\"topbar\">\n      <div>\n        <h1 class=\"title\">Assignments</h1>\n        <p class=\"subtitle\" id=\"assignSub\"></p>\n      </div>\n      <div class=\"profile-menu-wrap\">\n        <button class=\"profile-btn\" id=\"profileBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Profile and settings\">M</button>\n        <div class=\"profile-menu\" id=\"profileMenu\" role=\"menu\" hidden>\n          <button class=\"profile-menu-item\" type=\"button\" role=\"menuitem\" data-action=\"settings\">Settings</button>\n          <button class=\"profile-menu-item signout\" type=\"button\" role=\"menuitem\" data-action=\"signout\">Sign out</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-inner\">\n        <div class=\"section-head\">\n          <h2>All Assignments</h2>\n          <span class=\"assign-total\" id=\"assignTotal\"></span>\n        </div>\n        <div class=\"assign-filters\" id=\"assignFilters\">\n          <button class=\"assign-filter active\" type=\"button\" data-filter=\"all\">All</button>\n          <span class=\"assign-filter-select-wrap\" id=\"classFilterWrap\">\n            <button class=\"assign-filter-select-btn\" id=\"classFilterBtn\" type=\"button\" aria-haspopup=\"listbox\" aria-expanded=\"false\">\n              <span id=\"classFilterLabel\">All Classes</span>\n              <svg class=\"assign-filter-arrow\" viewBox=\"0 0 10 6\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\">\n                <path d=\"M1 1l4 4 4-4\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n              </svg>\n            </button>\n            <div class=\"assign-class-menu\" id=\"classFilterMenu\" role=\"listbox\" aria-label=\"Filter by class\" hidden>\n              <button class=\"assign-class-option selected\" type=\"button\" role=\"option\" aria-selected=\"true\" data-course=\"\">All Classes</button>\n            </div>\n          </span>\n          <button class=\"assign-filter\" type=\"button\" data-filter=\"overdue\">Missing</button>\n          <button class=\"assign-filter\" type=\"button\" data-filter=\"upcoming\">Upcoming</button>\n          <button class=\"assign-filter\" type=\"button\" data-filter=\"submitted\">Submitted</button>\n          <button class=\"assign-filter\" type=\"button\" data-filter=\"graded\">Graded</button>\n        </div>\n        <div id=\"assignListBody\"></div>\n      </div>\n    </div>\n  </div>\n\n  <nav class=\"app-nav\" aria-label=\"Main navigation\">\n    <div class=\"app-nav-inner\" id=\"dock\">\n      <button class=\"nav-link\" type=\"button\" data-page=\"home\" data-href=\"/home\">\n        <span class=\"label\">Home</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"courses\" data-href=\"/courses\">\n        <span class=\"label\">Courses</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"grades\" data-href=\"/grades\">\n        <span class=\"label\">Grades</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link active\" type=\"button\" data-page=\"assignments\">\n        <span class=\"label\">Assignments</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"files\" data-href=\"/files\">\n        <span class=\"label\">Files</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"calendar\" data-href=\"/calendar\">\n        <span class=\"label\">Calendar</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"messages\" data-href=\"/messages\">\n        <span class=\"label\">Messages</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"contacts\" data-href=\"/contacts\">\n        <span class=\"label\">Contacts</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"settings\" data-href=\"/settings\">\n        <span class=\"label\">Settings</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-more\" type=\"button\" id=\"navMore\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\" aria-label=\"More pages\" hidden>\n        <span class=\"label\"><svg viewBox=\"0 0 16 4\" width=\"16\" height=\"4\" aria-hidden=\"true\"><circle cx=\"2\" cy=\"2\" r=\"1.75\"/><circle cx=\"8\" cy=\"2\" r=\"1.75\"/><circle cx=\"14\" cy=\"2\" r=\"1.75\"/></svg></span>\n        <span class=\"dot\"></span>\n      </button>\n    </div>\n    <div class=\"nav-more-menu\" id=\"navMoreMenu\" role=\"menu\" aria-label=\"More pages\" hidden></div>\n  </nav>\n\n  \n\n\n  \n  \n";
const SCRIPT_JS = "\n    // ---- Links by id (2026-10-07, Martin) ----\n    // A real class (Schoology/Classroom ids are digits) links as\n    // assignment?id=<id> and course-home?id=<section id>; the sample classes\n    // (word ids like \"apchem\") keep ?course=&title=. Pages read both.\n    function avgIsId(v) { return /^\\d{1,24}$/.test(String(v == null ? '' : v)); }\n    function avgCourseQ(course) { return (avgIsId(course) ? 'id=' : 'course=') + encodeURIComponent(course == null ? '' : course); }\n    function avgAssignHref(course, title, id, extra) {\n      extra = extra || '';\n      if (avgIsId(id) && avgIsId(course)) return `/assignment?id=${id}${extra}`;\n      return `/assignment?course=${encodeURIComponent(course == null ? '' : course)}&title=${encodeURIComponent(title || '')}${avgIsId(id) ? `&id=${id}` : ''}${extra}`;\n    }\n\n    // Potato PC Mode on every page (2026-10-04, per Martin). The saved\n    // setting turns off all CSS animations and transitions, makes animate()\n    // calls and smooth scrolling instant, and drops the slanted page title.\n    // Same code as app/lib/theme-boot.ts, which runs it before first paint in\n    // the app; this copy covers the preview and pages theme-boot skips.\n    (function () {\n    var POTATO_CSS = \"body.potato-mode,body.potato-mode *,body.potato-mode *::before,body.potato-mode *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;filter:none!important;text-shadow:none!important}html:has(body.potato-mode){scroll-behavior:auto!important}body.potato-mode,body.potato-mode *{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif!important}body.potato-mode h1.title{font-style:normal!important;transform:none!important}body.potato-mode .trend.has-popup:focus-visible{outline:2px solid currentColor;outline-offset:2px}\";\n    function potatoOn() { return !!(document.body && document.body.classList.contains(\"potato-mode\")); }\n    function applyPotato() {\n      var on = false;\n      try { on = (JSON.parse(localStorage.getItem(\"schoolagy_settings_options\") || \"{}\") || {}).potatoMode === true; } catch (e) {}\n      if (document.body) document.body.classList.toggle(\"potato-mode\", on);\n      if (!document.getElementById(\"potatoStyle\")) {\n        var st = document.createElement(\"style\");\n        st.id = \"potatoStyle\";\n        st.textContent = POTATO_CSS;\n        (document.head || document.documentElement).appendChild(st);\n      }\n      var EP = window.Element && Element.prototype;\n      if (EP && !EP.__potatoPatched) {\n        EP.__potatoPatched = true;\n        var anim = EP.animate;\n        if (anim) EP.animate = function (frames, opts) {\n          if (potatoOn()) opts = (typeof opts === \"number\" || opts == null) ? { duration: 0 } : Object.assign({}, opts, { duration: 0, delay: 0, endDelay: 0, iterations: 1 });\n          return anim.call(this, frames, opts);\n        };\n        var siv = EP.scrollIntoView;\n        if (siv) EP.scrollIntoView = function (arg) {\n          if (potatoOn() && arg && typeof arg === \"object\") arg = Object.assign({}, arg, { behavior: \"auto\" });\n          return siv.call(this, arg);\n        };\n        [\"scrollTo\", \"scrollBy\"].forEach(function (name) {\n          [EP, window].forEach(function (target) {\n            var fn = target[name];\n            if (!fn) return;\n            target[name] = function (a, b) {\n              if (potatoOn() && a && typeof a === \"object\") a = Object.assign({}, a, { behavior: \"auto\" });\n              return b === undefined ? fn.call(this, a) : fn.call(this, a, b);\n            };\n          });\n        });\n      }\n    }\n      applyPotato();\n      window.addEventListener('storage', function (e) { if (e.key === 'schoolagy_settings_options') applyPotato(); });\n    })();\n\n    // Bottom nav \"More\" overflow. Shows as many pages as fit without\n    // cutting a label off (\"Cour...\"); the rest go in the More menu.\n    // The current page always stays in the bar.\n    (function () {\n      const nav = document.querySelector('.app-nav');\n      const inner = nav && nav.querySelector('.app-nav-inner');\n      const more = document.getElementById('navMore');\n      const menu = document.getElementById('navMoreMenu');\n      if (!inner || !more || !menu) return;\n      const links = Array.from(inner.querySelectorAll('.nav-link'));\n\n      const cut = () =>\n        inner.scrollWidth > inner.clientWidth + 1 ||\n        links.some(l => !l.hidden && l.querySelector('.label').scrollWidth > l.querySelector('.label').clientWidth + 1);\n\n      function fit() {\n        closeMenu();\n        links.forEach(l => { l.hidden = false; });\n        more.hidden = true;\n        if (!cut()) return;\n        more.hidden = false;\n        // Hide from the right, but never the current page.\n        for (let i = links.length - 1; i >= 1 && cut(); i--) {\n          if (!links[i].classList.contains('active')) links[i].hidden = true;\n        }\n        const hidden = links.filter(l => l.hidden);\n        more.classList.toggle('has-active', hidden.some(l => l.classList.contains('active')));\n        menu.textContent = '';\n        hidden.forEach(l => {\n          const item = document.createElement('button');\n          item.type = 'button';\n          item.className = 'nav-more-item' + (l.classList.contains('active') ? ' active' : '');\n          item.setAttribute('role', 'menuitem');\n          const text = document.createElement('span'); text.textContent = l.querySelector('.label').textContent; item.appendChild(text);\n          item.addEventListener('click', () => { closeMenu(); l.click(); });\n          menu.appendChild(item);\n        });\n      }\n\n      function openMenu() {\n        const navBox = nav.getBoundingClientRect();\n        const innerBox = inner.getBoundingClientRect();\n        menu.style.right = Math.max(0, navBox.right - innerBox.right) + 'px';\n        menu.hidden = false;\n        nav.classList.add('more-open');\n        more.setAttribute('aria-expanded', 'true');\n        const first = menu.querySelector('.nav-more-item');\n        if (first) first.focus();\n      }\n      function closeMenu() {\n        if (menu.hidden) return;\n        menu.hidden = true;\n        nav.classList.remove('more-open');\n        more.setAttribute('aria-expanded', 'false');\n      }\n\n      more.addEventListener('click', e => {\n        e.stopPropagation();\n        menu.hidden ? openMenu() : closeMenu();\n      });\n      document.addEventListener('click', e => { if (!menu.contains(e.target)) closeMenu(); });\n      document.addEventListener('keydown', e => {\n        if (e.key === 'Escape' && !menu.hidden) { closeMenu(); more.focus(); }\n        if (!menu.hidden && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {\n          const items = Array.from(menu.querySelectorAll('.nav-more-item'));\n          const i = items.indexOf(document.activeElement);\n          const next = items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length];\n          if (next) { e.preventDefault(); next.focus(); }\n        }\n      });\n\n      fit();\n      if (window.ResizeObserver) new ResizeObserver(fit).observe(nav);\n      else window.addEventListener('resize', fit);\n      if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);\n    })();\n  \n\n\n    // ------------------------------------------------------------------\n    // Shared appearance (accent + background) — 2026-09-08, per Martin:\n    // \"wallpapers + accent colors don't save across pages.\" Settings'\n    // Appearance section (and onboarding's Theme step) are the only\n    // writers of schoolagy_appearance; every other real app page,\n    // including this one, applies whatever's saved there, read-only, on\n    // its own load — same shared-localStorage-record pattern already\n    // used for schoolagy_dark_mode/schoolagy_profile.\n    // ------------------------------------------------------------------\n    (function () {\n      function darken(hex, amount) {\n        const n = parseInt(hex.slice(1), 16);\n        const r = Math.max(0, ((n >> 16) & 255) * (1 - amount));\n        const g = Math.max(0, ((n >> 8) & 255) * (1 - amount));\n        const b = Math.max(0, (n & 255) * (1 - amount));\n        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');\n      }\n      function applyAppearance() {\n        let saved = null;\n        try {\n          const raw = localStorage.getItem('schoolagy_appearance');\n          if (raw) saved = JSON.parse(raw);\n        } catch {}\n        if (!saved) return;\n        const root = document.documentElement.style;\n        if (saved.accent) {\n          root.setProperty('--accent', saved.accent);\n          root.setProperty('--accent-dark', saved.accentDark || darken(saved.accent, 0.22));\n        }\n        if (saved.background === 'white') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#f4f4f6';\n        } else if (saved.background === 'black') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#0c0c0e';\n        } else if (saved.background) {\n          document.body.style.backgroundImage = `url(\"${saved.background}\")`;\n          document.body.style.backgroundColor = '';\n        }\n      }\n      applyAppearance();\n      window.addEventListener('storage', e => {\n        if (e.key === 'schoolagy_appearance') applyAppearance();\n      });\n    })();\n\n    // ------------------------------------------------------------------\n    // Sample data — same six courses/colors as /home and\n    // /courses (id/name/color only; this page doesn't need the\n    // course-code/period fields /courses's table shows), and the\n    // same OVERDUE/UPCOMING/HISTORY values /course-home's\n    // Assignment List uses, so a given assignment reads identically no\n    // matter which page it's viewed from.\n    // ------------------------------------------------------------------\n\n    // ------------------------------------------------------------------\n    // Course customization persistence — added 2026-09-08. Renaming,\n    // recoloring, or reordering a course (in /home's Customize editor\n    // or /courses's Reorder tool — the only places that WRITE these)\n    // used to be invisible everywhere else, since every page just\n    // re-generated its own hardcoded COURSES array from scratch on load.\n    // schoolagy_course_custom holds per-course name/color overrides\n    // (object keyed by course id, only actually-customized courses\n    // present); schoolagy_course_order holds a full custom ordering of\n    // course ids (array), written only once the user has actually\n    // reordered. This page only READS both — applyCourseCustomizationsInPlace()\n    // is called right after the raw array literal below, mutating COURSES\n    // in place, so it's already the customized/reordered version before\n    // anything on this page ever renders it. Same defensive\n    // try/catch-per-key style as AVERAGES_DARK_MODE_KEY in /settings.\n    // ------------------------------------------------------------------\n    const AVERAGES_COURSE_CUSTOM_KEY = 'schoolagy_course_custom';\n    const AVERAGES_COURSE_ORDER_KEY = 'schoolagy_course_order';\n    function loadCourseCustom() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_CUSTOM_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return {};\n    }\n    function loadCourseOrder() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_ORDER_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return null;\n    }\n    // Subject table (2026-10-01, per Martin): each course gets a color that\n    // fits its subject, picked from its name. First match wins, so specific\n    // subjects come before broad ones (\"Computer Science\" before \"Science\",\n    // \"Physical Education\" before \"Physics\"). A color the student picked in\n    // the course's info pop-up still wins over this. No match keeps the\n    // course's own color. All colors pass 4.5:1 with white text.\n    const COURSE_SUBJECTS = [\n      [/\\bchem/, '🧪', '#1b7f67'],\n      [/\\bbio|anatom|physiolog/, '🧬', '#387f33'],\n      [/\\bphysical ed|(^|[^a-z])p\\.?e\\.?($|[^a-z])|fitness|\\bweight/, '🏃', '#c2562b'],\n      [/\\bhealth/, '🩺', '#c0404a'],\n      [/\\bphysics/, '⚛️', '#4a56b8'],\n      [/astronom/, '🔭', '#3b3f8f'],\n      [/environment|\\bearth|geolog/, '🌍', '#2f7f63'],\n      [/robotic/, '🤖', '#55697d'],\n      [/computer|programming|coding|\\bcs[ap]?\\b|software/, '💻', '#2d6f8f'],\n      [/engineer/, '⚙️', '#6a6478'],\n      [/government|civics|politic/, '🏛️', '#2f4f8a'],\n      [/econ/, '📈', '#2e7d4f'],\n      [/psych/, '🧠', '#9a4583'],\n      [/geograph/, '🗺️', '#4c7a5a'],\n      [/histor/, '📜', '#9a5a2a'],\n      [/statistic|\\bstats?\\b/, '📊', '#2f72a8'],\n      [/geometr|\\btrig/, '📐', '#3e64b0'],\n      [/calc|algebra|\\bmath/, '🧮', '#2f5fb3'],\n      [/english|literature|\\blit\\b|writing|composition|language arts|reading/, '📖', '#a63a4f'],\n      [/spanish|french|german|chinese|mandarin|japanese|korean|latin|italian|\\basl\\b|sign language|language/, '🗣️', '#7a4fae'],\n      [/theat|drama/, '🎭', '#a3364b'],\n      [/music|band|choir|orchestra|chorus/, '🎵', '#6b48a8'],\n      [/photo/, '📷', '#4f5d6e'],\n      [/culinary|cooking|\\bfoods?\\b|nutrition/, '🍳', '#b05a26'],\n      [/\\barts?\\b|drawing|painting|ceramic|sculpt|design/, '🎨', '#b03f7a'],\n      [/business|marketing|accounting|financ/, '💼', '#3d5f6e'],\n      [/journalism|yearbook|newspaper/, '📰', '#5c5c6e'],\n      [/science/, '🔬', '#2b7b8c'],\n    ];\n    function courseSubject(name) {\n      const n = String(name || '').toLowerCase();\n      return COURSE_SUBJECTS.find(([re]) => re.test(n)) || null;\n    }\n\n    function applyCourseCustomizationsInPlace(courses) {\n      const custom = loadCourseCustom();\n      // Mutates each course object's own fields in place (never clones,\n      // never reassigns `courses` itself) so the `const COURSES = [...]`\n      // literal a few lines below stays exactly that — a literal array —\n      // for scripts/port-pages.mjs's data-overrides transform to match\n      // and rewrite for live Schoology data. This function only edits\n      // the array's contents/order after that binding already exists.\n      courses.forEach(c => {\n        const subject = courseSubject(c.name);\n        if (subject) c.color = subject[2];\n        Object.assign(c, custom[c.id] || {});\n      });\n      const order = loadCourseOrder();\n      if (order && order.length) {\n        const byId = new Map(courses.map(c => [c.id, c]));\n        const ordered = order.filter(id => byId.has(id)).map(id => byId.get(id));\n        // A course not present in the saved order (e.g. added to the demo\n        // data after the order was saved) still shows up, just appended.\n        courses.forEach(c => { if (!order.includes(c.id)) ordered.push(c); });\n        courses.splice(0, courses.length, ...ordered);\n      }\n    }\n    const COURSES = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.COURSES) || [\n      { id: 'apchem', name: 'AP Chemistry', color: '#a67a22' },\n      { id: 'algebra2', name: 'Algebra II', color: '#5b6ea3' },\n      { id: 'english10', name: 'English 10', color: '#6b8f5e' },\n      { id: 'ushistory', name: 'U.S. History', color: '#a15c4f' },\n      { id: 'spanish3', name: 'Spanish III', color: '#8a6ba1' },\n      { id: 'pe', name: 'PE', color: '#4f8c8a' },\n    ];\n    applyCourseCustomizationsInPlace(COURSES);\n    function findCourse(id) { return COURSES.find(c => c.id === id); }\n\n    /* Course names, colors and assignment titles/due dates all come from\n       whatever the teacher typed into Schoology, so dropping them straight\n       into innerHTML lets a title like `<img src=x onerror=...>` run in this\n       app's own origin — everything data-derived below goes through here\n       first. String() rather than assuming a string, since scores arrive as\n       numbers. Do NOT wrap values that are themselves markup (assignRowHTML's\n       own output, TYPE_LABEL's literals). Verified by verify/xss-test.mjs. */\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, ch => (\n        { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch]\n      ));\n    }\n\n    const TYPE_LABEL = { assignment: 'Assignment', discussion: 'Discussion', assessment: 'Quiz' };\n\n    const HISTORY = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.HISTORY) || {\n      apchem: { points: [72, 79, 84, 88, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'], titles: [['Intro Lab Safety Quiz', 'assessment'], ['Stoichiometry Problem Set', 'assignment'], ['Molarity Discussion', 'discussion'], ['Gas Laws Test', 'assessment'], ['Lab Report #3', 'assignment']] },\n      algebra2: { points: [94, 96, 93, 97, 95], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'], titles: [['Warm-Up Quiz 1', 'assessment'], ['Systems of Equations HW', 'assignment'], ['Factoring Discussion', 'discussion'], ['Unit 1 Test', 'assessment'], ['Practice Set 6', 'assignment']] },\n      english10: { points: [88, 82, 79, 76, 73], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'], titles: [['Reading Journal 1', 'assignment'], ['Vocabulary Quiz', 'assessment'], ['Chapter 3 Discussion', 'discussion'], ['Essay Draft', 'assignment'], ['Grammar Check', 'assessment']] },\n      ushistory: { points: [89, 93, 88, 92, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'], titles: [['Colonial Era Notes', 'assignment'], ['Primary Source Quiz', 'assessment'], ['Revolution Discussion', 'discussion'], ['Timeline Project', 'assignment'], ['Unit 1 Exam', 'assessment']] },\n      spanish3: { points: [76, 80, 83, 85, 87], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'], titles: [['Vocabulario Quiz', 'assessment'], ['Conjugación Practice', 'assignment'], ['Conversación Discussion', 'discussion'], ['Listening Check', 'assessment'], ['Composición 1', 'assignment']] },\n      pe: { points: [96, 98, 95, 97, 96], dates: ['Aug 2', 'Aug 6', 'Aug 10', 'Aug 16', 'Aug 22'], titles: [['Fitness Log 1', 'assignment'], ['Rules Quiz', 'assessment'], ['Team Strategy Discussion', 'discussion'], ['Skills Check', 'assessment'], ['Fitness Log 2', 'assignment']] },\n    };\n\n    const OVERDUE = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.OVERDUE) || [\n      { type: 'assignment', title: 'Lab Report #4', courseId: 'apchem', due: 'Fri Aug 21' },\n      { type: 'discussion', title: 'Chapter 6 Discussion', courseId: 'english10', due: 'Thu Aug 20' },\n      { type: 'discussion', title: 'Reading Response', courseId: 'ushistory', due: 'Wed Aug 19' },\n    ];\n    const UPCOMING = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.UPCOMING) || [\n      { type: 'assessment', title: 'Unit 2 Quiz', courseId: 'algebra2', due: 'Mon Aug 24' },\n      { type: 'assignment', title: 'Vocab Worksheet', courseId: 'spanish3', due: 'Tue Aug 25' },\n      { type: 'assignment', title: 'Problem Set 7', courseId: 'algebra2', due: 'Wed Aug 26' },\n      { type: 'assignment', title: 'Titration Lab Prep', courseId: 'apchem', due: 'Mon Aug 24' },\n    ];\n    // Recently Submitted — turned in but not graded yet, sitting between\n    // Upcoming and Graded in the assignment lifecycle (added 2026-08-29,\n    // per Martin's request). Same values /assignment reads for its\n    // own lookup, so a submitted item matches wherever it's viewed.\n    const SUBMITTED = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.SUBMITTED) || [\n      { type: 'assignment', title: 'Molarity Practice Set', courseId: 'apchem', submittedOn: 'Sat Aug 22' },\n      { type: 'assessment', title: 'Quiz Corrections', courseId: 'algebra2', submittedOn: 'Sun Aug 23' },\n      { type: 'assignment', title: 'Composición 2', courseId: 'spanish3', submittedOn: 'Fri Aug 21' },\n    ];\n\n    // Signed in with real data (2026-10-06); a demo sign-in shows the samples.\n    // Schoology can't say what's turned in, so its bundle has no SUBMITTED:\n    // empty, never the sample list.\n    const AV_LIVE = !!(window.__AVERAGES__ && window.__AVERAGES__.data) && window.__AVERAGES__.mode !== 'demo';\n    if (AV_LIVE && !Array.isArray(window.__AVERAGES__.data.SUBMITTED)) SUBMITTED.length = 0;\n\n    const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];\n    function fmtAug(day) { return `${DOW[new Date(2026, 7, day).getDay()]} Aug ${day}`; }\n    function dayNum(dateStr) { const parts = dateStr.trim().split(/\\s+/); return parseInt(parts[parts.length - 1], 10); }\n\n    // ------------------------------------------------------------------\n    // Build the three item lists across all six courses. Graded items\n    // come from HISTORY (one entry per course per score); Missing/\n    // Upcoming come straight from OVERDUE/UPCOMING. Every item ends up\n    // with a normalized {status, type, title, courseId, day, due,\n    // score?} shape — the same fields assignRowHTML() below expects,\n    // whichever list it came from.\n    // ------------------------------------------------------------------\n    // Live items with a real due time sort by it (day of month alone breaks across months).\n    const sortDay = x => (x.dueAt && !isNaN(Date.parse(x.dueAt)) ? Date.parse(x.dueAt) : dayNum(x.due));\n    const overdueItems = OVERDUE\n      .map(o => ({ status: 'overdue', type: o.type, title: o.title, courseId: o.courseId, day: sortDay(o), due: o.due, id: o.id }))\n      .sort((a, b) => a.day - b.day);\n    const upcomingItems = UPCOMING\n      .map(u => ({ status: 'upcoming', type: u.type, title: u.title, courseId: u.courseId, day: sortDay(u), due: u.due, id: u.id }))\n      .sort((a, b) => a.day - b.day);\n    const submittedItems = SUBMITTED\n      .map(s => ({ status: 'submitted', type: s.type, title: s.title, courseId: s.courseId, day: dayNum(s.submittedOn), due: s.submittedOn, id: s.id }))\n      .sort((a, b) => b.day - a.day);\n    const gradedItems = [];\n    const LIVE_GRADES = window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.RECENT_GRADES;\n    if (Array.isArray(LIVE_GRADES)) {\n      // Signed in: newest first, as the API sends them.\n      LIVE_GRADES.forEach((r, i) => gradedItems.push({ status: 'graded', type: 'assignment', title: String(r.title || ''), courseId: String(r.courseId || ''), day: LIVE_GRADES.length - i, due: '', score: r.pct, id: r.id }));\n    }\n    COURSES.forEach(course => {\n      const hist = HISTORY[course.id];\n      if (Array.isArray(LIVE_GRADES) || !hist || !Array.isArray(hist.titles)) return;\n      hist.dates.forEach((d, i) => {\n        const day = dayNum(d);\n        gradedItems.push({ status: 'graded', type: hist.titles[i][1], title: hist.titles[i][0], courseId: course.id, day, due: fmtAug(day), score: hist.points[i] });\n      });\n    });\n    gradedItems.sort((a, b) => b.day - a.day);\n    // \"All\" tab shows a trimmed recent slice of Graded (30 graded items\n    // across six courses is too many to dump into a combined view) —\n    // the dedicated Graded tab below still shows every one.\n    const gradedRecent = gradedItems.slice(0, 8);\n\n    function assignRowHTML(item) {\n      // A class that isn't in the list (2026-10-06): a neutral row, not an error.\n      const course = findCourse(item.courseId) || { name: '', color: 'var(--text-faint)' };\n      const dueText = item.status === 'graded' ? (typeof item.score === 'number' && isFinite(item.score) ? `Graded · ${item.score}%` : 'Graded')\n        : item.status === 'overdue' ? (item.due ? `Missing · ${item.due}` : 'Missing')\n        : item.status === 'submitted' ? (item.due ? `Submitted · ${item.due}` : 'Submitted')\n        : (item.due ? `Due ${item.due}` : 'Upcoming');\n      const dest = avgAssignHref(item.courseId, item.title, item.id);\n      return `\n        <div class=\"assign-row ${escapeHtml(item.status)}\" style=\"--row-course-color: ${escapeHtml(course.color)}\" role=\"link\" tabindex=\"0\" data-href=\"${escapeHtml(dest)}\" aria-label=\"${escapeHtml(item.title)}, ${escapeHtml(course.name)}\">\n          <span class=\"assign-tick\"></span>\n          <div class=\"assign-text\">\n            <p class=\"assign-course\" style=\"color: ${escapeHtml(course.color)}\">${escapeHtml(course.name)}</p>\n            <p class=\"assign-title\">${escapeHtml(item.title)}</p>\n            <p class=\"assign-meta\">${TYPE_LABEL[item.type] || 'Assignment'}</p>\n          </div>\n          <span class=\"assign-due\">${escapeHtml(dueText)}</span>\n        </div>`;\n    }\n\n    function assignGroupHTML(label, items) {\n      if (!items.length) return '';\n      return `<p class=\"assign-group-label\">${label}</p>` + items.map(assignRowHTML).join('');\n    }\n\n    // Class filter (added 2026-09-03) — narrows every status tab down to\n    // one course, on top of whichever status filter is already active;\n    // '' (the \"All Classes\" option) means no narrowing. Kept as its own\n    // variable rather than baked into the four *Items arrays above, since\n    // those are computed once at load and this needs to re-filter on\n    // every dropdown change without losing the original full lists.\n    let currentStatusFilter = 'all';\n    let selectedCourseId = '';\n\n    function renderAssignList(filter) {\n      const body = document.getElementById('assignListBody');\n      const byCourse = arr => selectedCourseId ? arr.filter(i => i.courseId === selectedCourseId) : arr;\n      const overdue = byCourse(overdueItems);\n      const upcoming = byCourse(upcomingItems);\n      const submitted = byCourse(submittedItems);\n      const graded = byCourse(gradedItems);\n      const gradedR = byCourse(gradedRecent);\n      let html = '';\n      if (filter === 'all') {\n        html = assignGroupHTML('Missing', overdue) + assignGroupHTML('Upcoming', upcoming) + assignGroupHTML('Recently Submitted', submitted) + assignGroupHTML('Recently Graded', gradedR);\n      } else if (filter === 'overdue') {\n        html = overdue.map(assignRowHTML).join('');\n      } else if (filter === 'upcoming') {\n        html = upcoming.map(assignRowHTML).join('');\n      } else if (filter === 'submitted') {\n        html = submitted.map(assignRowHTML).join('');\n      } else if (filter === 'graded') {\n        html = graded.map(assignRowHTML).join('');\n      }\n      body.innerHTML = html || '<p class=\"assign-empty\">Nothing here yet.</p>';\n    }\n    renderAssignList('all');\n\n    document.getElementById('assignFilters').addEventListener('click', e => {\n      const btn = e.target.closest('.assign-filter');\n      if (!btn) return;\n      document.querySelectorAll('.assign-filter').forEach(b => b.classList.toggle('active', b === btn));\n      currentStatusFilter = btn.dataset.filter;\n      renderAssignList(currentStatusFilter);\n    });\n\n    // Class filter — a custom dropdown (2026-09-03, replacing an earlier\n    // native <select> per Martin: \"can you make a custom dropdown for\n    // selecting a class to filter by\") built the same way this page's\n    // own profile menu already is: a button that toggles a floating\n    // panel, closed on an outside click or Escape. Options are built\n    // from the same COURSES list every other lookup on this page already\n    // uses, so there's no second hardcoded class list to drift out of\n    // sync, each with a small color dot matching that course's own\n    // identity color everywhere else in the app. Selecting a real class\n    // (anything but \"All Classes\") turns the pill the accent color,\n    // matching the status pills' own active state, and it stays that\n    // color until reset back to \"All Classes\".\n    const classFilterBtn = document.getElementById('classFilterBtn');\n    const classFilterLabel = document.getElementById('classFilterLabel');\n    const classFilterMenu = document.getElementById('classFilterMenu');\n    const classFilterWrap = document.getElementById('classFilterWrap');\n    COURSES.forEach(c => {\n      const opt = document.createElement('button');\n      opt.className = 'assign-class-option';\n      opt.type = 'button';\n      opt.setAttribute('role', 'option');\n      opt.setAttribute('aria-selected', 'false');\n      opt.dataset.course = c.id;\n      opt.innerHTML = `<span class=\"assign-class-dot\" style=\"background:${escapeHtml(c.color)}\"></span>${escapeHtml(c.name)}`;\n      classFilterMenu.appendChild(opt);\n    });\n    function openClassMenu() { classFilterMenu.hidden = false; classFilterBtn.setAttribute('aria-expanded', 'true'); }\n    function closeClassMenu() { classFilterMenu.hidden = true; classFilterBtn.setAttribute('aria-expanded', 'false'); }\n    classFilterBtn.addEventListener('click', () => { if (classFilterMenu.hidden) openClassMenu(); else closeClassMenu(); });\n    document.addEventListener('click', e => { if (!classFilterMenu.hidden && !e.target.closest('.assign-filter-select-wrap')) closeClassMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !classFilterMenu.hidden) { closeClassMenu(); classFilterBtn.focus(); } });\n\n    // Moves the class-filter pill between \"right after All\" (its resting\n    // spot) and \"the far end of the row, after Graded\" (2026-09-03, per\n    // Martin: \"when a class is selected it moves to the far right in an\n    // animation\"). A real DOM move (insertAdjacentElement/appendChild),\n    // not just a visual `order` shuffle, so keyboard tab order always\n    // matches what's on screen. Animated with a small FLIP (First, Last,\n    // Invert, Play): read the pill's position before the move, let the\n    // browser lay it out in its new spot, then animate a transform from\n    // the old position to the new one instead of letting it just snap.\n    const assignFiltersEl = document.getElementById('assignFilters');\n    const allFilterBtn = assignFiltersEl.querySelector('.assign-filter[data-filter=\"all\"]');\n    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n    function moveClassFilterWrap(toEnd) {\n      const first = classFilterWrap.getBoundingClientRect();\n      if (toEnd) assignFiltersEl.appendChild(classFilterWrap);\n      else allFilterBtn.insertAdjacentElement('afterend', classFilterWrap);\n      if (prefersReducedMotion) return;\n      const last = classFilterWrap.getBoundingClientRect();\n      const dx = first.left - last.left;\n      const dy = first.top - last.top;\n      if (!dx && !dy) return;\n      classFilterWrap.style.transition = 'none';\n      classFilterWrap.style.transform = `translate(${dx}px, ${dy}px)`;\n      requestAnimationFrame(() => {\n        classFilterWrap.style.transition = 'transform 0.28s ease';\n        classFilterWrap.style.transform = '';\n      });\n      classFilterWrap.addEventListener('transitionend', () => { classFilterWrap.style.transition = ''; }, { once: true });\n    }\n\n    const assignListBodyEl = document.getElementById('assignListBody');\n    classFilterMenu.addEventListener('click', e => {\n      const opt = e.target.closest('.assign-class-option');\n      if (!opt) return;\n      selectedCourseId = opt.dataset.course;\n      classFilterLabel.textContent = opt.dataset.course ? COURSES.find(c => c.id === opt.dataset.course).name : 'All Classes';\n      classFilterMenu.querySelectorAll('.assign-class-option').forEach(o => {\n        const isSelected = o === opt;\n        o.classList.toggle('selected', isSelected);\n        o.setAttribute('aria-selected', String(isSelected));\n      });\n      classFilterWrap.classList.toggle('active', !!selectedCourseId);\n      assignListBodyEl.classList.toggle('class-filtered', !!selectedCourseId);\n      moveClassFilterWrap(!!selectedCourseId);\n      renderAssignList(currentStatusFilter);\n      closeClassMenu();\n    });\n\n    // Rows navigate to their own assignment detail page (2026-08-29) —\n    // delegated on the shared body container since renderAssignList()\n    // rebuilds its innerHTML on every filter change.\n    document.getElementById('assignListBody').addEventListener('click', e => {\n      const row = e.target.closest('.assign-row');\n      if (row) window.location.href = row.dataset.href;\n    });\n    document.getElementById('assignListBody').addEventListener('keydown', e => {\n      if (e.key !== 'Enter' && e.key !== ' ') return;\n      const row = e.target.closest('.assign-row');\n      if (!row) return;\n      e.preventDefault();\n      window.location.href = row.dataset.href;\n    });\n\n    document.getElementById('assignTotal').textContent = `${overdueItems.length + upcomingItems.length + submittedItems.length + gradedItems.length} total`;\n    document.getElementById('assignSub').textContent = `${overdueItems.length} missing · ${upcomingItems.length} upcoming · ${submittedItems.length} submitted`;\n\n    // Nav — Home/Courses/Assignments are real links between real pages\n    // (same full-mesh convention /course-home and\n    // /course-materials already use); the rest stay visual-only\n    // placeholders until those pages exist.\n    document.querySelectorAll('.nav-link').forEach(link => {\n      link.addEventListener('click', () => {\n        if (link.dataset.href) { window.location.href = link.dataset.href; return; }\n        document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));\n        link.classList.add('active');\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Profile menu — same behavior as every other page.\n    // ------------------------------------------------------------------\n    const profileBtn = document.getElementById('profileBtn');\n    // Shared profile photo/name (2026-09-07) — /settings's Edit\n    // Profile modal is the only place this is ever set, but every other\n    // page's top-right profile button used to just show a fixed \"M\" no\n    // matter what was saved there: the button never read anything back,\n    // so a photo you set in Settings was invisible the moment you left\n    // it. schoolagy_profile is the same localStorage record\n    // /settings writes on every save; this is read-only here.\n    (function () {\n      var profile = null;\n      try {\n        var raw = localStorage.getItem('schoolagy_profile');\n        if (raw) profile = JSON.parse(raw);\n      } catch (e) {}\n      if (!profile) return;\n      if (profile.photo) {\n        profileBtn.style.backgroundImage = 'url(\"' + profile.photo + '\")';\n        profileBtn.style.backgroundSize = 'cover';\n        profileBtn.style.backgroundPosition = 'center';\n        profileBtn.textContent = '';\n      } else if (profile.name) {\n        profileBtn.textContent = profile.name.trim().charAt(0).toUpperCase() || 'M';\n      }\n    })();\n    const profileMenu = document.getElementById('profileMenu');\n    function openProfileMenu() { profileMenu.hidden = false; profileBtn.setAttribute('aria-expanded', 'true'); }\n    function closeProfileMenu() { profileMenu.hidden = true; profileBtn.setAttribute('aria-expanded', 'false'); }\n    profileBtn.addEventListener('click', () => { if (profileMenu.hidden) openProfileMenu(); else closeProfileMenu(); });\n    document.addEventListener('click', e => { if (!profileMenu.hidden && !e.target.closest('.profile-menu-wrap')) closeProfileMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !profileMenu.hidden) { closeProfileMenu(); profileBtn.focus(); } });\n    profileMenu.querySelectorAll('.profile-menu-item').forEach(item => {\n      item.addEventListener('click', () => {\n        if (item.dataset.action === 'settings') { window.location.href = '/settings'; return; }\n        closeProfileMenu();\n      });\n    });\n  \n\n\n    // Back link (2026-10-01, per Martin: \"where it returns to ... is always\n    // wrong\"). Every page records itself in a short per-tab trail; a page's\n    // back link then says and goes to the page before it (\"Back to AP\n    // Chemistry Hub\", \"Back to Grades\"...). With no trail (the page was\n    // opened directly) the page's own default back link is left alone.\n    (function () {\n      const SELF = '/assignments';\n      const KEY = 'averages_nav_trail';\n      const here = SELF + location.search;\n      const label = (document.title || '').replace(/^Averages\\s*[—-]\\s*/, '') || 'Assignments';\n      let trail = [];\n      try { trail = JSON.parse(sessionStorage.getItem(KEY) || '[]'); } catch {}\n      if (!Array.isArray(trail)) trail = [];\n      const last = trail[trail.length - 1];\n      if (last && last.href === here) last.label = label;                 // reload\n      else if (trail.length > 1 && trail[trail.length - 2].href === here) { trail.pop(); trail[trail.length - 1].label = label; } // went back\n      else trail.push({ href: here, label });\n      trail = trail.slice(-20);\n      try { sessionStorage.setItem(KEY, JSON.stringify(trail)); } catch {}\n\n      const btn = document.querySelector('.back-link');\n      const prev = trail[trail.length - 2];\n      if (!btn || !prev) return;\n      const fresh = btn.cloneNode(false);          // same button, minus old click handlers\n      fresh.removeAttribute('onclick');\n      const icon = btn.querySelector('svg');\n      if (icon) fresh.appendChild(icon.cloneNode(true));\n      const text = document.createElement('span');\n      text.textContent = 'Back to ' + prev.label;\n      fresh.appendChild(text);\n      fresh.addEventListener('click', () => { window.location.href = prev.href; });\n      btn.replaceWith(fresh);\n    })();\n  ";

export default function Page() {
  return (
    <LegacyPage
      title={TITLE}
      styleCss={STYLE_CSS}
      bodyHtml={BODY_HTML}
      scriptJs={SCRIPT_JS}
      requiresAuth={true}
      usesSavedTheme={true}
      hasUploads={false}
      externalScripts={[]}
      pageId={"assignments"}
    />
  );
}
